#if UNITY_EDITOR
using System;
using System.IO;
using System.Linq;
using LastRail.Battle;
using Newtonsoft.Json.Linq;
using NUnit.Framework;
namespace LastRail.Tests.EditMode {
 public class BRefitModelTests {
  public static JObject Trace(string name)=>(JObject)((JArray)JObject.Parse(File.ReadAllText("D:/Project/LASTRAIL/QA/CommanderS1-20260922/combat-b-refit-http-traces-20261003.json"))["traces"]).Single(t=>(string)t["name"]==name)["response"].DeepClone();
  public static JArray Cells()=>new JArray(new JObject{["slot"]=0,["type"]="BCB01",["rank"]=1},new JObject{["slot"]=1,["type"]="BCB06",["rank"]=1});
  static BRefitHttpResponse Ok(JObject b)=>new BRefitHttpResponse(200,"no-store",BRefitRequest.Version,b);
  [Test] public void ActualOriginalReadCreatesImmutableSupportedSourceAndCanonicalDefinitionHash(){var p=Trace("READ_SOURCE_EMPTY");var s=new BRefitSnapshot(p,"a");Assert.AreEqual(0,s.Revision);Assert.AreEqual("91e78c7de844f2758becea9998c3850d1b6df66cadd0400c9156e40ee699090e",s.DefinitionHash);Assert.IsFalse(s.StartReady);Assert.IsNull(s.Refit);p["rankSource"]["ranks"][0]["rank"]=5;Assert.AreEqual(1,s.RankRevision);Assert.AreEqual(1,(int)s.Capture()["rankSource"]["ranks"][0]["rank"]);}
  [Test] public void SaveFreezesHashesAndUsesOnlyAuthoritativeRanksAndSelectedCells(){var state=new BRefitSnapshot(Trace("READ_SOURCE_EMPTY"),"a");var cells=Cells();var r=BRefitRequest.Save(state,cells,"original");cells[0]["rank"]=5;r.Body["sourceHash"]="other";Assert.AreEqual(state.SourceHash,(string)r.Body["sourceHash"]);Assert.AreEqual(1,(int)r.Body["refits"][0]["rank"]);CollectionAssert.AreEquivalent(new[]{"version","expectedRevision","selectionRevision","rankRevision","definitionHash","sourceHash","refits"},r.Body.Properties().Select(p=>p.Name));Assert.AreEqual("/_local/combat-b/refit",BRefitRequest.Path);}
  [TestCase("hash")][TestCase("source")][TestCase("definitions")][TestCase("rank")][TestCase("duplicate-rank")][TestCase("instance")][TestCase("slot")][TestCase("revision")][TestCase("ready")][TestCase("unknown")][TestCase("empty-history")]
  public void OriginalReadBoundaryRejectsAlteredOrMissingContract(string what){var p=Trace("READ_SOURCE_EMPTY");if(what=="hash")p["definitionHash"]=new string('f',64);if(what=="source")p["sourceHash"]="bad";if(what=="definitions")p["definitions"][0]["values"][0]=999;if(what=="rank")p["rankSource"]["ranks"][0]["rank"]=6;if(what=="duplicate-rank")p["rankSource"]["ranks"][1]["type"]="BCB01";if(what=="instance")p["rankSource"]["instances"][1]["instanceId"]="a_physical1";if(what=="slot")p["rankSource"]["instances"][0]["slot"]=5;if(what=="revision")p["selectionRevision"]=0;if(what=="ready")p["startReady"]=true;if(what=="unknown")p["accountId"]="a";if(what=="empty-history")p["savedSourceHash"]=new string('f',64);Assert.Catch(()=>new BRefitSnapshot(p,"a"));}
  [TestCase("missing")][TestCase("duplicate")][TestCase("R5")][TestCase("instance")][TestCase("foreignslot")][TestCase("badkey")][TestCase("newline")]
  public void SaveCannotInventRanksPhysicalSourceOrInvalidIdempotencyKey(string what){var cells=Cells();if(what=="missing")cells.RemoveAt(1);if(what=="duplicate")cells[1]["slot"]=0;if(what=="R5")cells[0]["rank"]=5;if(what=="instance")cells[0]["instanceId"]="fake";if(what=="foreignslot")cells[1]["slot"]=3;Assert.Catch(()=>BRefitRequest.Save(new BRefitSnapshot(Trace("READ_SOURCE_EMPTY"),"a"),cells,what=="badkey"?"has space":what=="newline"?"key\n":"key"));}
  [Test] public void ControllerPublishesOneReadAndKeepsOriginalReceiptSeparateFromFreshCurrentState(){using var c=new BRefitController("a");BRefitRequest pending=null;int notified=0;c.Bind(r=>pending=r,()=>notified++);c.Read();c.AcceptResponse(pending,Ok(Trace("READ_SOURCE_EMPTY")));var original=c.Save(Cells(),"save");c.AcceptResponse(original,Ok(Trace("SAVE")));Assert.AreEqual(0,c.State.Revision,"ACK must not invent current source");Assert.AreEqual(1,(int)c.Receipt["revision"]);c.Read();c.AcceptResponse(pending,Ok(Trace("RESTORED_CURRENT_READ")));var current=c.State.Capture();c.ReplayOriginal();Assert.AreSame(original,pending);c.AcceptResponse(original,Ok(Trace("SAVE")));Assert.IsTrue(JToken.DeepEquals(current,c.State.Capture()));Assert.AreEqual(4,notified);}
  [Test] public void ConflictRequiresFreshReadAndANewIntendedKey(){using var c=new BRefitController("a");BRefitRequest pending=null;c.Bind(r=>pending=r);c.Read();c.AcceptResponse(pending,Ok(Trace("READ_SOURCE_EMPTY")));var original=c.Save(Cells(),"stale");c.AcceptResponse(original,new BRefitHttpResponse(409,"no-store",BRefitRequest.Version,new JObject{["accepted"]=false,["errorCode"]="combat_b_refit_revision_conflict"}));Assert.Throws<InvalidOperationException>(()=>c.Save(Cells(),"new"));Assert.Throws<InvalidOperationException>(()=>c.ReplayOriginal());c.Read();c.AcceptResponse(pending,Ok(Trace("READ_SOURCE_EMPTY")));Assert.Throws<InvalidOperationException>(()=>c.Save(Cells(),"stale"));Assert.AreEqual("fresh",c.Save(Cells(),"fresh").Key);}
  [TestCase("account")][TestCase("physical")][TestCase("rank")][TestCase("type")][TestCase("hash")][TestCase("revision")][TestCase("ready")]
  public void AcknowledgementMustMatchTheImmutableOriginalCommandAndPhysicalCapture(string what){using var c=new BRefitController("a");BRefitRequest pending=null;c.Bind(r=>pending=r);c.Read();c.AcceptResponse(pending,Ok(Trace("READ_SOURCE_EMPTY")));var r=c.Save(Cells(),"save");var ack=Trace("SAVE");if(what=="account")ack["refit"]["accountId"]="b";if(what=="physical")ack["refit"]["cars"][0]["instanceId"]="other";if(what=="rank")ack["refit"]["cars"][0]["rank"]=5;if(what=="type")ack["refit"]["cars"][0]["type"]="BCB02";if(what=="hash")ack["sourceHash"]=new string('f',64);if(what=="revision")ack["revision"]=2;if(what=="ready")ack["startReady"]=true;Assert.Catch(()=>c.AcceptResponse(r,Ok(ack)));Assert.IsNull(c.Receipt);Assert.AreEqual(0,c.State.Revision);}
  [Test] public void RebindUnbindAndDisposeDoNotPublishOldRequestsOrDuplicateCallbacks(){using var c=new BRefitController("a");BRefitRequest pending=null;int count=0;Action<BRefitRequest> first=r=>pending=r;c.Bind(first,()=>count++);c.Read();var old=pending;c.Unbind(first);c.Bind(r=>pending=r,()=>count++);c.AcceptResponse(old,Ok(Trace("READ_SOURCE_EMPTY")));Assert.AreEqual(0,count);Assert.IsNull(c.State);c.Read();c.AcceptResponse(pending,Ok(Trace("READ_SOURCE_EMPTY")));Assert.AreEqual(1,count);c.Dispose();c.AcceptResponse(pending,Ok(Trace("READ_SOURCE_EMPTY")));Assert.AreEqual(1,count);Assert.Throws<ObjectDisposedException>(()=>c.Read());}
  [TestCase(401)][TestCase(403)] public void AuthorizationDenialStopsReadSaveReplayAndDoesNotResetOnBind(int status){using var c=new BRefitController("a");BRefitRequest pending=null;Action<BRefitRequest> handler=r=>pending=r;c.Bind(handler);c.Read();c.AcceptResponse(pending,new BRefitHttpResponse(status,"no-store",BRefitRequest.Version,new JObject{["accepted"]=false,["errorCode"]="auth_session_invalid"}));Assert.Throws<InvalidOperationException>(()=>c.Read());c.Bind(handler);Assert.Throws<InvalidOperationException>(()=>c.Read());}
  [Test] public void StaleHistoryIsPreservedAndNeverUpgradedToNewSharedRanks(){var old=Trace("READ_SAVED");old["rankSource"]["ranks"][0]["rank"]=5;old["rankSource"]["revision"]=2;old["sourceHash"]=new string('f',64);old["eligibilityError"]="combat_b_rank_revision_conflict";var s=new BRefitSnapshot(old,"a");Assert.AreEqual(1,(int)s.Refit["cars"][0]["rank"]);Assert.AreEqual(5,(int)s.Capture()["rankSource"]["ranks"][0]["rank"]);}
  [Test] public void ANewCommandCannotKeepThePreviousCommandsReceiptAfterUnknownCommit(){using var c=new BRefitController("a");BRefitRequest p=null;c.Bind(r=>p=r);c.Read();c.AcceptResponse(p,new BRefitHttpResponse(200,"no-store",BRefitRequest.Version,Trace("READ_SOURCE_EMPTY")));var a=c.Save(Cells(),"a");c.AcceptResponse(a,new BRefitHttpResponse(200,"no-store",BRefitRequest.Version,Trace("SAVE")));c.Read();c.AcceptResponse(p,new BRefitHttpResponse(200,"no-store",BRefitRequest.Version,Trace("READ_SAVED")));var cells=Cells();cells[0]["type"]="BCB02";var b=c.Save(cells,"b");c.AcceptResponse(b,new BRefitHttpResponse(503,"no-store",BRefitRequest.Version,new JObject{["accepted"]=false,["errorCode"]="combat_b_refit_storage_unavailable"}));Assert.AreSame(b,c.OriginalRequest);Assert.IsNull(c.Receipt,"An ACK for A is not an ACK for unknown B");}
  [Test] public void OriginalReplayCannotReplaceTheAcceptedReceiptWithAnAlteredIdentity(){using var c=new BRefitController("a");BRefitRequest p=null;c.Bind(r=>p=r);c.Read();c.AcceptResponse(p,new BRefitHttpResponse(200,"no-store",BRefitRequest.Version,Trace("READ_SOURCE_EMPTY")));var request=c.Save(Cells(),"original");c.AcceptResponse(request,new BRefitHttpResponse(200,"no-store",BRefitRequest.Version,Trace("SAVE")));var before=c.Receipt;c.ReplayOriginal();var altered=Trace("SAVE");altered["receiptId"]="changed-original";Assert.Catch(()=>c.AcceptResponse(request,new BRefitHttpResponse(200,"no-store",BRefitRequest.Version,altered)));Assert.IsTrue(JToken.DeepEquals(before,c.Receipt));}
  [TestCase("origin")][TestCase("userinfo")][TestCase("header")][TestCase("newline")][TestCase("expired")]
  public void PrivateIntakeCannotRedirectCredentialScopeOrAcceptInvalidMetadata(string part){var x=new JObject{["origin"]="http://127.0.0.1:12345",["accountId"]="a",["accessExpiresAt"]=DateTimeOffset.UtcNow.AddHours(1).ToUnixTimeMilliseconds(),["headers"]=new JObject{["Authorization"]="Bearer a.b.c",["X-Combat-B-Refit-Version"]=BRefitRequest.Version}};if(part=="origin")x["origin"]="http://example.test:12345";if(part=="userinfo")x["origin"]="http://name@127.0.0.1:12345";if(part=="header")x["headers"]["X-Combat-B-Refit-Version"]=BSelectionRequest.Version;if(part=="newline")x["headers"]["Authorization"]="Bearer a.b.c\n";if(part=="expired")x["accessExpiresAt"]=1;Assert.Catch(()=>new BRefitPrivateIntake(x));}
  [Test] public void ResponseVersionAndCacheHeadersCannotPublishUntrustedRead(){using var c=new BRefitController("a");BRefitRequest pending=null;c.Bind(r=>pending=r);c.Read();Assert.Catch(()=>c.AcceptResponse(pending,new BRefitHttpResponse(200,"public",BRefitRequest.Version,Trace("READ_SOURCE_EMPTY"))));Assert.IsNull(c.State);Assert.Catch(()=>c.AcceptResponse(pending,new BRefitHttpResponse(200,"no-store",BSelectionRequest.Version,Trace("READ_SOURCE_EMPTY"))));Assert.IsNull(c.State);}
 }
}
